import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Heart, Instagram, Facebook, Twitter, Mail } from 'lucide-react';

const Footer = () => {
  return (
    <footer style={{
      background: 'linear-gradient(180deg, #FAF6F2 0%, #F3EBE6 100%)',
      borderTop: '1px solid rgba(221,183,176,0.25)',
      padding: '72px 2rem 32px',
      position: 'relative',
      zIndex: 10,
    }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: '3rem',
          marginBottom: '3rem',
        }}>
          {/* Brand */}
          <div>
            <div style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.6rem', fontWeight: 600, color: '#3D2B38', marginBottom: '0.5rem' }}>
              Struvive Emolings
            </div>
            <div style={{ fontFamily: 'Manrope, sans-serif', fontSize: '0.82rem', color: '#9B7A8A', lineHeight: 1.8, marginBottom: '1.2rem' }}>
              A safe emotional sanctuary where emotions are understood, healed, and transformed into peace and freedom.
            </div>
            <div style={{ display: 'flex', gap: '0.8rem' }}>
              {[Instagram, Facebook, Twitter, Mail].map((Icon, i) => (
                <motion.a
                  key={i}
                  href="#"
                  whileHover={{ scale: 1.1, y: -2 }}
                  style={{
                    width: '36px',
                    height: '36px',
                    borderRadius: '50%',
                    background: 'rgba(221,183,176,0.15)',
                    border: '1px solid rgba(221,183,176,0.3)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: '#DDB7B0',
                  }}
                >
                  <Icon size={15} />
                </motion.a>
              ))}
            </div>
          </div>

          {/* Quick Links */}
          <div>
            <div style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.1rem', fontWeight: 600, color: '#3D2B38', marginBottom: '1rem' }}>
              Navigate
            </div>
            {[
              { label: 'Home', path: '/' },
              { label: 'About Us', path: '/about' },
              { label: 'Services', path: '/services' },
              { label: 'Blog', path: '/blog' },
              { label: 'Contact', path: '/contact' },
              { label: 'Book a Session', path: '/book' },
            ].map(link => (
              <div key={link.path} style={{ marginBottom: '0.5rem' }}>
                <Link
                  to={link.path}
                  style={{
                    fontFamily: 'Manrope, sans-serif',
                    fontSize: '0.85rem',
                    color: '#9B7A8A',
                    transition: 'color 0.3s',
                  }}
                  onMouseEnter={e => e.target.style.color = '#DDB7B0'}
                  onMouseLeave={e => e.target.style.color = '#9B7A8A'}
                >
                  {link.label}
                </Link>
              </div>
            ))}
          </div>

          {/* Services */}
          <div>
            <div style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.1rem', fontWeight: 600, color: '#3D2B38', marginBottom: '1rem' }}>
              Services
            </div>
            {['Anxiety Support', 'Emotional Healing', 'Stress Management', 'Student Counseling', 'Relationship Guidance', 'Self-Esteem Therapy', 'Mindfulness Wellness'].map(s => (
              <div key={s} style={{ marginBottom: '0.5rem', fontFamily: 'Manrope, sans-serif', fontSize: '0.85rem', color: '#9B7A8A' }}>
                {s}
              </div>
            ))}
          </div>

          {/* Contact */}
          <div>
            <div style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.1rem', fontWeight: 600, color: '#3D2B38', marginBottom: '1rem' }}>
              Reach Out
            </div>
            <div style={{ fontFamily: 'Manrope, sans-serif', fontSize: '0.85rem', color: '#9B7A8A', lineHeight: 2 }}>
              <div>hello@struviveemolings.com</div>
              <div>Monday–Friday, 9am–6pm</div>
              <div style={{ marginTop: '1rem', color: '#DDB7B0', fontStyle: 'italic', fontFamily: 'Cormorant Garamond, serif', fontSize: '1rem' }}>
                "You are worthy of healing."
              </div>
            </div>
          </div>
        </div>

        {/* Divider */}
        <div style={{
          height: '1px',
          background: 'linear-gradient(90deg, transparent, rgba(221,183,176,0.4), transparent)',
          margin: '2rem 0',
        }} />

        {/* Quote & Copyright */}
        <div style={{ textAlign: 'center' }}>
          <div style={{
            fontFamily: 'Cormorant Garamond, serif',
            fontSize: '1.1rem',
            fontStyle: 'italic',
            color: '#9B7A8A',
            marginBottom: '1rem',
          }}>
            "Every storm runs out of rain. Every dark night turns into day."
          </div>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '0.4rem',
            fontFamily: 'Manrope, sans-serif',
            fontSize: '0.78rem',
            color: '#B8C4B2',
          }}>
            <span>© 2025 Struvive Emolings. Made with</span>
            <Heart size={12} fill="#DDB7B0" color="#DDB7B0" />
            <span>for healing souls.</span>
          </div>
          <div style={{ marginTop: '0.5rem', display: 'flex', justifyContent: 'center', gap: '1.5rem' }}>
            {['Privacy Policy', 'Terms of Service', 'Cookie Policy'].map(item => (
              <a key={item} href="#" style={{
                fontFamily: 'Manrope, sans-serif',
                fontSize: '0.75rem',
                color: '#B8C4B2',
              }}>
                {item}
              </a>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
